CREATE TABLE IF NOT EXISTS `DocumentFolder` (`id` int NOT NULL AUTO_INCREMENT, `dossierId` int NOT NULL, `name` varchar(191) NOT NULL, `status` varchar(191) NOT NULL DEFAULT 'INCOMPLETE', `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` datetime(3) NOT NULL, PRIMARY KEY (`id`), KEY `DocumentFolder_dossierId_fkey` (`dossierId`), CONSTRAINT `DocumentFolder_dossierId_fkey` FOREIGN KEY (`dossierId`) REFERENCES `Dossier` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `StudentTask` (`id` int NOT NULL AUTO_INCREMENT, `userId` int NOT NULL, `dossierId` int, `type` enum('PAYMENTS','DOCUMENTS','UNIVERSITIES','GENERAL') NOT NULL DEFAULT 'GENERAL', `title` varchar(191) NOT NULL, `description` longtext, `amount` decimal(10,2), `currency` varchar(191) DEFAULT 'TND', `folder` varchar(191), `status` enum('OPEN','DONE') NOT NULL DEFAULT 'OPEN', `assignedAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `completedAt` datetime(3), `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` datetime(3) NOT NULL, PRIMARY KEY (`id`), KEY `StudentTask_userId_fkey` (`userId`), CONSTRAINT `StudentTask_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User` (`id`) ON DELETE CASCADE, INDEX `StudentTask_userId_idx` (`userId`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
ALTER TABLE `UniversityInfo` ADD COLUMN `status` enum('AWAITING_PAYMENT','APPLIED','ACCEPTED','REJECTED') NOT NULL DEFAULT 'APPLIED', ADD COLUMN `city` varchar(191), ADD COLUMN `language` varchar(191), ADD COLUMN `appliedAt` datetime(3), ADD COLUMN `decidedAt` datetime(3), ADD COLUMN `isFinalChoice` tinyint(1) NOT NULL DEFAULT 0, ADD COLUMN `offerDocumentId` int;
ALTER TABLE `Document` ADD COLUMN `storedPath` varchar(191), ADD COLUMN `mimeType` varchar(191), ADD COLUMN `uploadedById` int;
